WITH kept_keys AS (SELECT brand, id FROM products INTERSECT SELECT brand, id FROM products WHERE supplier_id IS NULL), verified AS (SELECT s.* FROM products s INNER JOIN kept_keys k ON s.brand = k.brand AND s.id = k.id) SELECT id, category, price, stock_qty, launch_date, tags, supplier_id, CASE WHEN category RLIKE '^(Home|Fashion)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS category_zone FROM verified
